def escape_markdown_cell(text):
    result = []
    backslash_count = 0
    for char in text:
        if char == '\\':
            backslash_count += 1
            result.append(char)
        elif char == '|':
            # If backslash_count is odd, the pipe is already escaped
            if backslash_count % 2 == 1:
                result.append(char)
            else:
                result.append('\\|')
            # Reset count after processing the pipe
            backslash_count = 0
        else:
            # Non-backslash, non-pipe character: reset count
            backslash_count = 0
            result.append(char)
    return ''.join(result)
```

