def escape_ini_value(s):
    # First, escape every backslash by doubling it
    escaped = s.replace('\\', '\\\\')

    # Then escape semicolons, equals signs, and hash characters by prefixing with backslash
    # Process each character to avoid double-escaping the backslashes we just added
    result = []
    for ch in escaped:
        if ch in ';=#':
            result.append('\\' + ch)
        else:
            result.append(ch)

    return ''.join(result)
